import{_ as r,C as n,c as l,o as d,a3 as a,G as o,j as s,a as i}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"First steps with Time Off","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/get-started/first-steps.md","filePath":"master/human-resources/time-off/get-started/first-steps.md","lastUpdated":1792041590000}'),f={name:"master/human-resources/time-off/get-started/first-steps.md"};function h(c,e,p,g,m,u){const t=n("ImagePopup");return d(),l("div",null,[e[0]||(e[0]=a(`<h1 id="first-steps-with-time-off" tabindex="-1">First steps with Time Off <a class="header-anchor" href="#first-steps-with-time-off" aria-label="Permalink to &quot;First steps with Time Off&quot;">​</a></h1><p>This tutorial walks through the whole leave flow with one example. You check a balance, ask for three days, approve them and see the balance change. Then you meet a new employee with no days, fix that with an allocation and try a refusal and a half day.</p><blockquote><p><strong>In simple words:</strong> You will book leave for Sarah Mitchell, then set up and test leave for Priya Sharma.</p></blockquote><p>Each step ends with a short note on what Aureus does behind the scenes. Links point to the pages that explain each screen. The dates are in 2026. If they are in the past, pick any future Monday to Wednesday.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Sarah Mitchell is the employee of the admin user, and she has 20 days of <strong>Paid Time Off</strong>. Priya Sharma is the employee from <a href="./../../employees/get-started/first-steps.html">First steps with Employees</a>. Sample data includes the seven leave types.</p></div><h2 id="the-map" tabindex="-1">The map <a class="header-anchor" href="#the-map" aria-label="Permalink to &quot;The map&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check balance  &gt;  Request 3 days  &gt;  Approve  &gt;  Check balance again (17)</span></span>
<span class="line"><span>Priya: request denied  &gt;  Allocation  &gt;  Approve  &gt;  Request accepted</span></span>
<span class="line"><span>Sick allocation  &gt;  Refuse a Sick Time Off request  &gt;  Half day  &gt;  Calendar</span></span></code></pre></div><h2 id="step-1-check-your-balance" tabindex="-1">Step 1: Check your balance <a class="header-anchor" href="#step-1-check-your-balance" aria-label="Permalink to &quot;Step 1: Check your balance&quot;">​</a></h2><ol><li>Open <code>Time Off → My Time → Dashboard</code>.</li><li>Find the card <strong>Paid Time Off</strong>. It shows <code>20.0</code> and the line <strong>Valid until 2026-12-31</strong>.</li><li>Find the card <strong>Pending Requests</strong>. It shows <code>0</code> and the line <strong>Time Off Requests</strong>.</li></ol>`,9)),o(t,{src:"/images1/time-off/to_fs_dashboard_balance.png",alt:"My Time dashboard with the Paid Time Off card showing 20.0, other types showing 0.0 and the Pending Requests card showing 0"}),e[1]||(e[1]=a('<p><strong>Behind the scenes:</strong> Aureus adds up the approved allocations of the type. Then it subtracts the days of every request that is not refused. See <a href="./../requests/my-time.html">My Time</a>.</p><h2 id="step-2-request-three-days-of-paid-time-off" tabindex="-1">Step 2: Request three days of Paid Time Off <a class="header-anchor" href="#step-2-request-three-days-of-paid-time-off" aria-label="Permalink to &quot;Step 2: Request three days of Paid Time Off&quot;">​</a></h2><ol><li>On the dashboard calendar, click the green <strong>New Time Off</strong> button. A window titled <strong>Create Leave</strong> opens.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Time Off Type:</em></strong> Required. Choose <strong>Paid Time Off</strong>.</li><li><strong><em>Request Date From:</em></strong> Required. Pick Monday, 19 October 2026.</li><li><strong><em>To Date:</em></strong> Required. Pick Wednesday, 21 October 2026.</li><li><strong><em>Description:</em></strong> Type <code>Family function</code>.</li></ul><p>The <strong>Duration</strong> line reads <code>3 working days</code>.</p>',5)),o(t,{src:"/images1/time-off/to_fs_request_form.png",alt:"Create Leave window with Paid Time Off, Request Date From Oct 19 2026, To Date Oct 21 2026, Duration 3 working days and description Family function"}),e[2]||(e[2]=s("ol",{start:"3"},[s("li",null,[i("Click "),s("strong",null,"Create"),i(". The request appears on the calendar as a bar from Monday to Wednesday.")])],-1)),o(t,{src:"/images1/time-off/to_fs_request_calendar.png",alt:"My Time calendar for October 2026 with a Paid Time Off bar titled Paid Time Off ERP Admin (3d) from 19 to 21 October"}),e[3]||(e[3]=a('<p>The bar title is the leave type, then the name of the logged in user, then the length. You are signed in as the user <strong>ERP Admin</strong>, whose employee is Sarah Mitchell. So the title reads <code>Paid Time Off ERP Admin (3d)</code>.</p><ol start="4"><li>Open <code>Time Off → My Time → Dashboard</code> again. The <strong>Paid Time Off</strong> card already shows <code>17.0</code> and <strong>Pending Requests</strong> shows <code>1</code>.</li></ol><p><strong>Behind the scenes:</strong> Aureus counts weekdays only. It also checks that the dates do not overlap another request. The saved request has the status <strong>To Approve</strong>. See <a href="./../requests/request-time-off.html">Request time off</a>.</p><h2 id="step-3-approve-the-request" tabindex="-1">Step 3: Approve the request <a class="header-anchor" href="#step-3-approve-the-request" aria-label="Permalink to &quot;Step 3: Approve the request&quot;">​</a></h2><ol><li>Open <code>Time Off → Management → Time off</code>.</li><li>Find the row of Sarah Mitchell. Click the three-dot icon at the end of the row.</li><li>Click <strong>Approve</strong>. The status badge changes to <strong>Approved</strong>. A <strong>Time Off approved</strong> message appears.</li></ol>',5)),o(t,{src:"/images1/time-off/to_fs_approve_menu.png",alt:"Management Time Offs list on the Waiting For Me tab with the row menu open on Sarah Mitchell's request showing Approve, Refuse, View, Edit and Delete"}),e[4]||(e[4]=a('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The list opens on the tab <strong>Waiting For Me</strong>. Click <strong>Default</strong> to see every request.</p></div><h2 id="step-4-check-the-balance-again" tabindex="-1">Step 4: Check the balance again <a class="header-anchor" href="#step-4-check-the-balance-again" aria-label="Permalink to &quot;Step 4: Check the balance again&quot;">​</a></h2><ol><li>Open <code>Time Off → My Time → Dashboard</code>.</li><li>The <strong>Paid Time Off</strong> card still shows <code>17.0</code>. <strong>Pending Requests</strong> is back to <code>0</code>.</li></ol>',3)),o(t,{src:"/images1/time-off/to_fs_balance_17.png",alt:"Dashboard with the Paid Time Off card showing 17.0 and Pending Requests showing 0 after the approval"}),e[5]||(e[5]=a('<p><strong>Behind the scenes:</strong> A pending request already lowers the balance. An approval keeps it lowered. A refusal gives the days back.</p><h2 id="step-5-a-request-from-priya-without-days" tabindex="-1">Step 5: A request from Priya without days <a class="header-anchor" href="#step-5-a-request-from-priya-without-days" aria-label="Permalink to &quot;Step 5: A request from Priya without days&quot;">​</a></h2><p>Priya has no <strong>Paid Time Off</strong> allocation yet. Try to book two days for her.</p><ol><li>Open <code>Time Off → Management → Time off</code>.</li><li>Click <strong>New Time off</strong>. The page is titled <strong>Create Time Off</strong>.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Employee Name:</em></strong> Required. Choose <strong>Priya Sharma</strong>. <strong>Department Name</strong> fills in by itself.</li><li><strong><em>Time Off Type:</em></strong> Required. Choose <strong>Paid Time Off</strong>.</li><li><strong><em>Request Date From:</em></strong> Pick 22 October 2026.</li><li><strong><em>To Date:</em></strong> Pick 23 October 2026.</li><li><strong><em>Description:</em></strong> Type <code>Annual leave request</code>.</li></ul><ol start="4"><li>Click <strong>Create</strong>. A <strong>Leave Request Denied</strong> message appears: <code>You do not have any allocated leave for Paid Time Off.</code> Nothing is saved and the form stays open.</li></ol>',6)),o(t,{src:"/images1/time-off/to_fs_priya_denied.png",alt:"Leave Request Denied notification saying You do not have any allocated leave for Paid Time Off"}),e[6]||(e[6]=a('<p><strong>Behind the scenes:</strong> A type with <strong>Requires Allocation: Yes</strong> needs approved days first. See <a href="./../setup/time-off-types.html">Leave types</a>.</p><h2 id="step-6-allocate-days-to-priya" tabindex="-1">Step 6: Allocate days to Priya <a class="header-anchor" href="#step-6-allocate-days-to-priya" aria-label="Permalink to &quot;Step 6: Allocate days to Priya&quot;">​</a></h2><ol><li>Open <code>Time Off → Management → Allocation</code>.</li><li>Click <strong>New Allocation</strong>.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Name:</em></strong> Type <code>Paid Time Off 2026</code>.</li><li><strong><em>Time Off Type:</em></strong> Choose <strong>Paid Time Off</strong>.</li><li><strong><em>Employee Name:</em></strong> Choose <strong>Priya Sharma</strong>.</li><li><strong><em>Allocation Type:</em></strong> Keep <strong>Regular</strong>. It means a fixed number of days.</li><li><strong><em>Date From:</em></strong> Pick 1 October 2026. Leave <strong>Date To</strong> empty. It shows <strong>No Limit</strong>.</li><li><strong><em>Allocation:</em></strong> Type <code>12</code>.</li><li><strong><em>Reason:</em></strong> Type <code>Annual leave 2026</code>.</li></ul>',4)),o(t,{src:"/images1/time-off/to_fs_allocation_form.png",alt:"Create Allocation form with Name Paid Time Off 2026, Paid Time Off, Priya Sharma, Regular, Date From Oct 1 2026, 12 days and reason Annual leave 2026"}),e[7]||(e[7]=a('<ol start="4"><li>Click <strong>Create</strong>. A <strong>Time Off created</strong> message appears. The app opens the allocation page with the state <strong>To Approve</strong>.</li><li>Open <code>Time Off → Management → Allocation</code> and click <strong>Default</strong>. On the row of Priya, click the three-dot icon and click <strong>Approve</strong>.</li></ol>',1)),o(t,{src:"/images1/time-off/to_fs_allocation_approved.png",alt:"Allocations list filtered by Priya showing Priya Sharma, Paid Time Off, 12.0000, Regular, status Approved"}),e[8]||(e[8]=a('<p><strong>Behind the scenes:</strong> Only approved allocations add to a balance. See <a href="./../allocations/manage-allocations.html">Manage allocations</a>.</p><h2 id="step-7-request-again-and-get-accepted" tabindex="-1">Step 7: Request again and get accepted <a class="header-anchor" href="#step-7-request-again-and-get-accepted" aria-label="Permalink to &quot;Step 7: Request again and get accepted&quot;">​</a></h2><ol><li>Repeat Step 5 with the same values.</li><li>Click <strong>Create</strong>. The request is saved with the status <strong>To Approve</strong>. A <strong>Time Off created</strong> message appears.</li></ol>',3)),o(t,{src:"/images1/time-off/to_fs_priya_accepted.png",alt:"Management Time Offs list filtered by Priya showing Paid Time Off, Annual leave request, 2026-10-22 to 2026-10-23, 2 working days, To Approve"}),e[9]||(e[9]=a('<h2 id="step-8-allocate-sick-time-off" tabindex="-1">Step 8: Allocate Sick Time Off <a class="header-anchor" href="#step-8-allocate-sick-time-off" aria-label="Permalink to &quot;Step 8: Allocate Sick Time Off&quot;">​</a></h2><p>Sick Time Off also needs an allocation before Aureus accepts a request. Without one, you see <code>You do not have any allocated leave for Sick Time Off.</code></p><p>Create a <strong>Sick Time Off</strong> allocation for Priya as in Step 6. Type <code>5</code> in <strong>Allocation</strong> and approve it.</p><h2 id="step-9-refuse-a-sick-time-off-request" tabindex="-1">Step 9: Refuse a Sick Time Off request <a class="header-anchor" href="#step-9-refuse-a-sick-time-off-request" aria-label="Permalink to &quot;Step 9: Refuse a Sick Time Off request&quot;">​</a></h2><ol><li>Open <code>Time Off → Management → Time off</code> and click <strong>New Time off</strong>. Choose <strong>Priya Sharma</strong> and <strong>Sick Time Off</strong>.</li><li>Pick 26 October 2026 for both dates. Type <code>Fever</code> in <strong>Description</strong>. Click <strong>Create</strong>. <strong>Duration</strong> reads <code>1 working day</code>.</li><li>Click the three-dot icon on its row and click <strong>Refuse</strong>. A <strong>Time Off refused</strong> message appears. The badge shows <strong>Refused</strong>.</li></ol>',5)),o(t,{src:"/images1/time-off/to_fs_refused.png",alt:"Management list filtered by Priya with the Paid Time Off request To Approve and the Sick Time Off request for 26 October with status Refused"}),e[10]||(e[10]=a('<h2 id="step-10-book-a-half-day" tabindex="-1">Step 10: Book a half day <a class="header-anchor" href="#step-10-book-a-half-day" aria-label="Permalink to &quot;Step 10: Book a half day&quot;">​</a></h2><ol><li>Open <code>Time Off → Management → Time off</code> and click <strong>New Time off</strong>.</li><li>Choose <strong>Priya Sharma</strong>. <strong>Department Name</strong> shows <strong>Operations</strong>. Choose <strong>Sick Time Off</strong>.</li><li>Pick 27 October 2026. Turn on <strong>Half Day</strong>. The <strong>To Date</strong> field hides and <strong>Period</strong> appears with <strong>Morning</strong> already chosen.</li><li><strong>Duration</strong> reads <code>0.5 day</code>. Type <code>Doctor appointment</code> in <strong>Description</strong>.</li></ol>',2)),o(t,{src:"/images1/time-off/to_fs_half_day.png",alt:"Management create form for Priya Sharma, Operations, Sick Time Off on Oct 27 2026 with Half Day on, Period Morning, Duration 0.5 day and description Doctor appointment"}),e[11]||(e[11]=a('<ol start="5"><li>Click <strong>Create</strong>. In the list, the <strong>Date To</strong> cell of a half day is empty.</li></ol><h2 id="step-11-see-the-calendar" tabindex="-1">Step 11: See the calendar <a class="header-anchor" href="#step-11-see-the-calendar" aria-label="Permalink to &quot;Step 11: See the calendar&quot;">​</a></h2><ol><li>Open <code>Time Off → Overview</code>. A calendar of the whole year opens.</li><li>Find the coloured bars. Each bar is a request, coloured by leave type.</li><li>Click a bar to view it.</li></ol>',3)),o(t,{src:"/images1/time-off/to_fs_overview_calendar.png",alt:"Overview year calendar 2026 with coloured bars for Paid Time Off and Sick Time Off in October and requests in other months"}),e[12]||(e[12]=a('<h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Time off overview</a></li><li><a href="./../setup/">Setup</a></li><li><a href="./../requests/request-time-off.html">Request time off</a></li><li><a href="./../requests/manage-requests.html">Manage requests</a></li><li><a href="./../requests/overview-calendar.html">Overview calendar</a></li></ul>',2))])}const y=r(f,[["render",h]]);export{_ as __pageData,y as default};
